"""Authentication endpoints: register, login, current user."""

from __future__ import annotations

import re
import sqlite3

from fastapi import APIRouter, Depends, status
from pydantic import BaseModel

from app.config import Settings, get_settings
from app.db import get_db, utc_now
from app.errors import bad_request, conflict, unauthorized
from app.security import (
 create_access_token,
 get_current_user,
 hash_password,
 password_problem,
 verify_password,
)

router = APIRouter(prefix="/api/auth", tags=["auth"])

USERNAME_RE = re.compile(r"^[A-Za-z0-9_-]{3,32}$")

class RegisterIn(BaseModel):
 username: str
 password: str

class UserOut(BaseModel):
 id: int
 username: str
 created_at: str

class LoginIn(BaseModel):
 username: str
 password: str

class TokenOut(BaseModel):
 access_token: str
 token_type: str = "bearer"
 expires_in: int

@router.post("/register", response_model=UserOut, status_code=status.HTTP_201_CREATED, summary="Create an account")
def register(
 data: RegisterIn,
 conn: sqlite3.Connection = Depends(get_db),
 settings: Settings = Depends(get_settings),
) -> UserOut:
 if not USERNAME_RE.match(data.username):
  raise bad_request("invalid_username", "Username must be 3-32 characters: letters, digits, _ or -.")
 if problem := password_problem(data.password):
  raise bad_request("weak_password", problem)
 try:
  cur = conn.execute(
   "INSERT INTO users (username, password_hash, created_at) VALUES (?, ?, ?)",
   (data.username, hash_password(data.password), utc_now()),
  )
 except sqlite3.IntegrityError:
  raise conflict("username_taken", "That username is already taken.")
 user_id = cur.lastrowid
 row = conn.execute("SELECT id, username, created_at FROM users WHERE id = ?", (user_id,)).fetchone()
 return UserOut(**row)

@router.post("/login", response_model=TokenOut, summary="Sign in")
def login(
 data: LoginIn,
 conn: sqlite3.Connection = Depends(get_db),
 settings: Settings = Depends(get_settings),
) -> TokenOut:
 row = conn.execute("SELECT id, username, password_hash FROM users WHERE username = ?", (data.username,)).fetchone()
 if not row or not verify_password(data.password, row["password_hash"]):
  audit(conn, "login_failed", detail=data.username)
  raise unauthorized("invalid_credentials", "Invalid username or password.")
 user_id = row["id"]
 audit(conn, "login", user_id=user_id)
 token = create_access_token(user_id, row["username"], settings)
 return TokenOut(access_token=token, expires_in=settings.token_ttl)

@router.get("/me", response_model=UserOut, summary="Current user")
def me(user: get_current_user) -> UserOut:
 return UserOut(id=user.id, username=user.username, created_at="")
