<script type="module">
import { apiFetch, ApiError, loadToken, clearToken, TOKEN_KEY } from "./js/api.js";
import { showMessage, el, clear, formValues, whileBusy, formatTime } from "./js/ui.js";

if (!loadToken()) {
 location.href = "login.html";
}

const usernameEl = document.getElementById("username");
const signoutBtn = document.getElementById("signout");
const addForm = document.getElementById("add-form");
const todoList = document.getElementById("todo-list");
const pager = document.getElementById("pager");
const prevBtn = document.getElementById("prev");
const nextBtn = document.getElementById("next");
const pageInfo = document.getElementById("page-info");
const filterAll = document.getElementById("filter-all");
const filterOpen = document.getElementById("filter-open");
const filterDone = document.getElementById("filter-done");

let currentPage = { limit: 20, offset: 0 };
let currentFilter = null;

async function loadUser() {
 try {
  const me = await apiFetch("/api/auth/me");
  usernameEl.textContent = me.username;
 } catch (err) {
  if (err instanceof ApiError && err.status === 401) {
   clearToken();
   location.href = "login.html";
  } else {
   showMessage("Failed to load user", "error");
  }
 }
}

function setActiveFilter(btn) {
 [filterAll, filterOpen, filterDone].forEach(b => b.classList.remove("active"));
 btn.classList.add("active");
}

filterAll.addEventListener("click", () => { currentFilter = null; setActiveFilter(filterAll); loadTodos(); });
filterOpen.addEventListener("click", () => { currentFilter = "false"; setActiveFilter(filterOpen); loadTodos(); });
filterDone.addEventListener("click", () => { currentFilter = "true"; setActiveFilter(filterDone); loadTodos(); });

async function loadTodos() {
 currentPage.offset = 0;
 await fetchPage();
}

async function fetchPage() {
 try {
  const query = new URLSearchParams({ limit: currentPage.limit, offset: currentPage.offset });
  if (currentFilter) query.set("done", currentFilter);
  const data = await apiFetch(`/api/todos?${query}`);
  renderTodos(data.items);
  updatePager(data);
 } catch (err) {
  if (err instanceof ApiError && err.status === 401) {
   clearToken();
   location.href = "login.html";
  } else {
   showMessage(err instanceof ApiError ? err.message : "Failed to load todos", "error");
  }
 }
}

function renderTodos(items) {
 clear(todoList);
 if (items.length === 0) {
  todoList.appendChild(el("p", { class: "muted" }, "No todos yet."));
  return;
 }
 for (const todo of items) {
  const item = el("div", { class: "list-item" + (todo.done ? " done" : ""), "data-id": todo.id },
   el("input", { type: "checkbox", checked: todo.done, "aria-label": "Mark done" }),
   el("span", { class: "grow title" }, todo.title),
   el("button", { class: "secondary rename", "aria-label": "Rename" }, "Rename"),
   el("button", { class: "danger delete", "aria-label": "Delete" }, "Delete")
  );
  item.querySelector("input").addEventListener("change", () => toggleDone(todo.id, item.querySelector("input").checked));
  item.querySelector(".rename").addEventListener("click", () => renameTodo(todo.id, item.querySelector(".title")));
  item.querySelector(".delete").addEventListener("click", () => deleteTodo(todo.id));
  todoList.appendChild(item);
 }
}

function updatePager(data) {
 const totalPages = Math.ceil(data.total / data.limit);
 const currentPageNum = Math.floor(data.offset / data.limit) + 1;
 pageInfo.textContent = `Page ${currentPageNum} of ${totalPages || 1} (${data.total} total)`;
 prevBtn.disabled = currentPageNum <= 1;
 nextBtn.disabled = currentPageNum >= totalPages;
 prevBtn.onclick = () => { currentPage.offset -= currentPage.limit; fetchPage(); };
 nextBtn.onclick = () => { currentPage.offset += currentPage.limit; fetchPage(); };
}

async function addTodo(e) {
 e.preventDefault();
 await whileBusy(addForm, async () => {
  const data = formValues(addForm);
  try {
   await apiFetch("/api/todos", { method: "POST", body: data });
   addForm.reset();
   await fetchPage();
  } catch (err) {
   showMessage(err instanceof ApiError ? err.message : "Failed to add todo", "error");
  }
 });
}

async function toggleDone(id, done) {
 try {
  await apiFetch(`/api/todos/${id}`, { method: "PATCH", body: { done } });
  await fetchPage();
 } catch (err) {
  showMessage(err instanceof ApiError ? err.message : "Failed to update todo", "error");
  await fetchPage();
 }
}

async function renameTodo(id, titleEl) {
 const currentTitle = titleEl.textContent;
 const newTitle = prompt("Rename todo:", currentTitle);
 if (newTitle === null || newTitle.trim() === currentTitle) return;
 try {
  await apiFetch(`/api/todos/${id}`, { method: "PATCH", body: { title: newTitle.trim() } });
  await fetchPage();
 } catch (err) {
  showMessage(err instanceof ApiError ? err.message : "Failed to rename todo", "error");
 }
}

async function deleteTodo(id) {
 if (!confirm("Delete this todo?")) return;
 try {
  await apiFetch(`/api/todos/${id}`, { method: "DELETE" });
  await fetchPage();
 } catch (err) {
  showMessage(err instanceof ApiError ? err.message : "Failed to delete todo", "error");
 }
}

signoutBtn.addEventListener("click", () => {
 clearToken();
 location.href = "login.html";
});

addForm.addEventListener("submit", addTodo);

await loadUser();
await loadTodos();
